-- Schema as it was generated by Hibernate (ddl-auto=update) before Flyway was introduced.
-- Existing databases are baselined at this version and never run this file.

CREATE TABLE app_users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      VARCHAR(100) NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    role          VARCHAR(50)  NOT NULL,
    CONSTRAINT uk_app_users_username UNIQUE (username)
);

CREATE TABLE pellet_entries (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    entry_date      DATE    NOT NULL,
    number_of_sacks INTEGER NOT NULL CHECK (number_of_sacks >= 1),
    user_id         BIGINT  NOT NULL REFERENCES app_users (id),
    CONSTRAINT uk_pellet_entries_user_date UNIQUE (user_id, entry_date)
);
